    AND PJTID = #{pjtid}


    AND STATUS = #{status}


    AND PRIORITY = #{priority}



    AND ASSIGNEE LIKE CONCAT('%', #{assignee}, '%')




    AND NAME LIKE CONCAT('%', #{name}, '%')




    AND DATE(CREATED_AT) >= #{dateFrom}




    AND DATE(CREATED_AT) <= #{dateTo}


AND IS_DELETED = 'N'

mapper.select:
SELECT STATUS as status, COUNT(*) as count FROM TB_DEFECT WHERE IS_DELETED = 'N'
AND PJTID = #{pjtid}
AND ASSIGNEE = #{assignee}
GROUP BY STATUS ORDER BY STATUS

SELECT PRIORITY as priority, COUNT(*) as count FROM TB_DEFECT WHERE IS_DELETED = 'N'
AND PJTID = #{pjtid}
AND ASSIGNEE = #{assignee}
GROUP BY PRIORITY ORDER BY CASE PRIORITY WHEN '높음' THEN 1 WHEN '보통' THEN 2 WHEN '낮음' THEN 3 ELSE 4 END

SELECT ID, TEST_ID, NAME, DESCRIPTION, PRIORITY, STATUS, DATE_FORMAT(CREATED_AT, '%Y-%m-%d %H:%i:%s') as CREATED_AT, ASSIGNEE, FIX_DUE_DATE, DATE_FORMAT(FIXED_DATE, '%Y-%m-%d %H:%i:%s') as FIXED_DATE, REMARKS, IS_DELETED, DATE_FORMAT(UPDATED_AT, '%Y-%m-%d %H:%i:%s') as UPDATED_AT, PJTID, AUTO_GENERATED FROM TB_DEFECT WHERE IS_DELETED = 'N' AND STATUS != '완료' AND FIX_DUE_DATE IS NOT NULL AND FIX_DUE_DATE <= DATE_ADD(NOW(), INTERVAL 3 DAY)
AND PJTID = #{pjtid}
AND ASSIGNEE = #{assignee}
ORDER BY FIX_DUE_DATE ASC

SELECT ID, TEST_ID, NAME, DESCRIPTION, PRIORITY, STATUS, DATE_FORMAT(CREATED_AT, '%Y-%m-%d %H:%i:%s') as CREATED_AT, ASSIGNEE, FIX_DUE_DATE, DATE_FORMAT(FIXED_DATE, '%Y-%m-%d %H:%i:%s') as FIXED_DATE, REMARKS, IS_DELETED, DATE_FORMAT(UPDATED_AT, '%Y-%m-%d %H:%i:%s') as UPDATED_AT, PJTID, AUTO_GENERATED FROM TB_DEFECT WHERE IS_DELETED = 'N' AND PJTID = #{pjtid}
AND STATUS = #{status}
AND PRIORITY = #{priority}
AND ASSIGNEE LIKE CONCAT('%', #{assignee}, '%')
ORDER BY CREATED_AT DESC

SELECT DATE(CREATED_AT) as createdDate, COUNT(*) as totalCount, SUM(CASE WHEN STATUS = '완료' THEN 1 ELSE 0 END) as completedCount, SUM(CASE WHEN STATUS = '진행중' THEN 1 ELSE 0 END) as inProgressCount, SUM(CASE WHEN STATUS = '대기' THEN 1 ELSE 0 END) as waitingCount FROM TB_DEFECT WHERE IS_DELETED = 'N'
AND DATE(CREATED_AT) >= #{dateFrom}
AND DATE(CREATED_AT) <= #{dateTo}
AND PJTID = #{pjtid}
GROUP BY DATE(CREATED_AT) ORDER BY createdDate DESC

SELECT ID, TEST_ID, NAME, DESCRIPTION, PRIORITY, STATUS, DATE_FORMAT(CREATED_AT, '%Y-%m-%d %H:%i:%s') as CREATED_AT, ASSIGNEE, FIX_DUE_DATE, DATE_FORMAT(FIXED_DATE, '%Y-%m-%d %H:%i:%s') as FIXED_DATE, REMARKS, IS_DELETED, DATE_FORMAT(UPDATED_AT, '%Y-%m-%d %H:%i:%s') as UPDATED_AT, PJTID, AUTO_GENERATED FROM TB_DEFECT WHERE IS_DELETED = 'N' AND AUTO_GENERATED = 'Y'
AND PJTID = #{pjtid}
AND STATUS = #{status}
ORDER BY CREATED_AT DESC
